package ama.transcript;
import ama.access.MeetingAccess;
import ama.contract.IdentityContracts.*;
import ama.contract.MinutesContracts.*;
import ama.contract.TaskContracts.*;
import ama.storage.FileRegistry;
import ama.task.*;
import org.springframework.jdbc.core.JdbcTemplate;
import javax.sql.DataSource;
import java.util.*;
import static ama.contract.MinutesContracts.*;
import static ama.contract.MinutesContracts.FailureCode.*;
/** Fixed authority-owned generation domain. Detached specs cannot adopt newly created rows. */
final class MinutesTaskDomainPolicy implements GenerationRetentionPolicy {
 private final JdbcTranscriptAuthority authority;private final JdbcTaskPreparations issuer;private final JdbcTemplate j;private MinutesExternalPreparation external;private final MinutesCandidateWriter writer;private final JdbcGenerationRetention retention;
 synchronized void install(MinutesExternalPreparation value){if(external!=null)throw new IllegalStateException("Minutes external preparation already installed");external=Objects.requireNonNull(value);}
 private record Adopted(Object scope,FileRegistry.LockedMeeting gate,Actor actor,MinutesGraphCapture.Graph graph,TaskSpec spec){}
 private static final class Existing {final Actor actor;final MeetingAccess.LockedIdentities identities;final MinutesGraphDiscovery.Discovery discovery;final TranscriptAcquisitionBudget.Ledger budget;FileRegistry.LockedMeeting gate;MinutesGraphCapture.Graph graph;Object scope;MeetingAccess.Locked lockedRoot;PublicationPreparation publication;final Acquisition purpose;Existing(Actor actor,MeetingAccess.LockedIdentities identities,MinutesGraphDiscovery.Discovery discovery,TranscriptAcquisitionBudget.Ledger budget,Acquisition purpose){this.actor=actor;this.identities=identities;this.discovery=discovery;this.budget=budget;this.purpose=purpose;}}
 MinutesTaskDomainPolicy(JdbcTranscriptAuthority authority,DataSource source){this.authority=authority;issuer=new JdbcTaskPreparations(source);j=new JdbcTemplate(source);j.setQueryTimeout(2);writer=new MinutesCandidateWriter(authority,issuer);if(!(authority.meetingAccess() instanceof ama.meeting.JdbcMeetingAccess access))throw new IllegalArgumentException("Actual JDBC minutes access required");retention=new JdbcGenerationRetention(source,issuer,access);}
 PreparedDomain adopt(Object scope,FileRegistry.LockedMeeting gate,Actor actor,MinutesGraphCapture.Graph graph,TaskSpec spec){authority.requireMinutesWrite(scope,gate,actor,graph);shape(spec);validateInput(spec);return issuer.issue(List.of(spec),Acquisition.TASK_MUTATION,new Adopted(scope,gate,actor,graph,spec),true);}
 public Optional<PreparedDomain> prepare(List<TaskSpec> specs,Acquisition purpose,boolean skip){
  if(specs!=null)specs=specs.stream().distinct().toList();
  if(specs==null||specs.size()!=1)throw new DomainPreparationUnavailableException();var spec=specs.getFirst();shape(spec);
  String producer=ama.minutes.MinutesGenerateProducer.compute(spec.subject().id(),spec.input().id(),spec.inputFingerprint(),spec.businessVersion(),spec.cancelEpoch(),authority.canonicalBudget(),()->false);require(producer.equals(spec.producerKey()),PROVENANCE_UNAVAILABLE);
  var plan=MinutesGraphDiscovery.discover(authority.dataSource(),spec.subject().id(),"STORED_INPUT",spec.input().id(),100000);var actor=new Actor((String)plan.root().get("owner_id"),Status.ACTIVE,Set.of(ama.contract.IdentityContracts.Role.USER));var ids=((ama.meeting.JdbcMeetingAccess)authority.meetingAccess()).tryLockHistoricalIdentities(actor,plan.identities(),skip);if(ids.isEmpty())return Optional.empty();var limits=new TranscriptAcquisitionBudget(16777216,16777216,16777216,268435456,134217728,8388608,128,256,256);var budget=limits.ledger(authority.readBudget(),authority.canonicalBudget(),()->false);JdbcMinutesFactsReader.charge(plan,budget);return Optional.of(issuer.issue(specs,purpose,new Existing(actor,ids.orElseThrow(),plan,budget,purpose),true));
 }
 public void requirePrepared(List<TaskSpec> specs,Acquisition purpose,PreparedDomain prepared){issuer.require(specs,purpose,prepared);}
 public boolean permitsDomainEffects(PreparedDomain prepared){return issuer.permitsEffects(prepared);}
 public boolean lockRoot(TaskSpec spec,boolean skip){throw new DomainPreparationUnavailableException();}
 public boolean lockRoots(List<TaskSpec> specs,boolean skip,PreparedDomain prepared){
  try{return lockAll(specs,skip,prepared);}catch(ama.contract.FileContracts.Unavailable|ama.contract.FileContracts.NotFound unavailable){if(skip)return false;throw unavailable;}catch(Failure raced){if(skip&&Set.of(PROVENANCE_UNAVAILABLE,PROFILE_UNAVAILABLE,CAPABILITY_UNAVAILABLE).contains(raced.code()))return false;throw raced;}
 }
 private boolean lockAll(List<TaskSpec> specs,boolean skip,PreparedDomain prepared){
  var value=issuer.value(prepared);issuer.require(specs,value instanceof Existing p?p.purpose:Acquisition.TASK_MUTATION,prepared);if(value instanceof Adopted a){require(specs.equals(List.of(a.spec())),PROVENANCE_UNAVAILABLE);authority.requireMinutesWrite(a.scope(),a.gate(),a.actor(),a.graph());return true;}if(!(value instanceof Existing p))throw new DomainPreparationUnavailableException();
  var root=authority.meetingAccess().lockPrepared(p.identities,specs.getFirst().subject().id(),skip);if(root.isEmpty())return false;authority.meetingAccess().requirePrepared(root.orElseThrow(),p.actor,p.discovery.meeting(),p.discovery.identities(),MeetingAccess.Action.EDIT);var gate=authority.fileRegistry().adopt(p.actor,p.discovery.meeting(),root.orElseThrow(),MeetingAccess.Action.EDIT);var scope=authority.minutesScope(gate,p.actor,p.discovery.meeting());var spec=specs.getFirst();boolean current=JdbcMinutesFactsReader.num(p.discovery.root(),"revision")==spec.businessVersion()&&JdbcMinutesFactsReader.num(p.discovery.root(),"cancel_epoch")==spec.cancelEpoch();
  p.graph=MinutesGraphCapture.captureTask(authority,scope,gate,p.actor,p.discovery,p.budget,current,()->p.publication=JdbcGenerationRetention.prelockPublication(authority.dataSource(),prepared,p.discovery.meeting()));p.gate=gate;p.scope=scope;p.lockedRoot=root.orElseThrow();if(current){JdbcMinutesGenerationPreparation.writable(p.discovery.root(),spec.businessVersion());require(p.graph.auxiliary().getOrDefault("publication",List.of()).isEmpty(),CAPABILITY_UNAVAILABLE);var inputs=p.discovery.tables().getOrDefault("generation_input",List.of()).stream().filter(r->spec.input().id().equals(r.get("id"))).toList();require(inputs.size()==1,PROVENANCE_UNAVAILABLE);for(String field:List.of("transcript_confirmation_id","template_revision_id","exclusion_revision_id","element_set_id"))require(Objects.equals(inputs.getFirst().get(field),p.discovery.root().get(field)),PROVENANCE_UNAVAILABLE);}return true;
 }
 public void validateInput(TaskSpec spec){shape(spec);var found=j.queryForList("SELECT g.id FROM generation_input g JOIN transcript_confirmation c ON c.id=g.transcript_confirmation_id JOIN transcript_revision r ON r.id=c.revision_id JOIN template_revision t ON t.id=g.template_revision_id JOIN exclusion_revision e ON e.id=g.exclusion_revision_id WHERE g.id=? AND g.meeting_id=? AND g.base_revision=? AND g.input_fingerprint=? AND g.scope='FULL' AND g.target_element_id IS NULL AND g.material_snapshot_id IS NULL AND c.meeting_id=g.meeting_id AND r.meeting_id=g.meeting_id AND r.kind='WORKING' AND e.meeting_id=g.meeting_id",String.class,spec.input().id(),spec.subject().id(),spec.businessVersion(),spec.inputFingerprint());require(found.size()==1,PROVENANCE_UNAVAILABLE);}
 public void validateOutput(TaskSpec spec,TaskResult result){if(result.outcome()==Outcome.RECONCILING)throw new DomainPreparationUnavailableException();if(result.outcome()==Outcome.SUCCEEDED){require(result.output()!=null&&"GENERATION_CANDIDATE".equals(result.output().kind()),PROVENANCE_UNAVAILABLE);require(j.queryForList("SELECT id FROM generation_candidate WHERE id=? AND meeting_id=? AND input_id=? AND base_revision=? AND input_fingerprint=? AND state='PENDING'",String.class,result.output().id(),spec.subject().id(),spec.input().id(),spec.businessVersion(),spec.inputFingerprint()).size()==1,PROVENANCE_UNAVAILABLE);}else require(result.output()==null,PROVENANCE_UNAVAILABLE);}
 private MinutesExternalPreparation installed(){if(external==null)throw new DomainPreparationUnavailableException();return external;}
 public void validateExternalRequest(TaskSpec spec,ama.contract.ExternalContracts.ExternalRequest request){shape(spec);require("MINUTES_GENERATE".equals(request.operationKind())&&("minutes:"+spec.input().id()).equals(request.businessKey())&&request.logicalRequestHash().equals(request.executionRequestHash())&&request.requestManifest().length()<=65536,PROVENANCE_UNAVAILABLE);}
 public ama.contract.ExternalContracts.ExternalRequest requireRequest(TaskSpec spec,ExternalOperationPort.PreparedRequest value){var request=installed().request(value);require(request.spec.equals(spec),PROVENANCE_UNAVAILABLE);return request.external;}
 private JdbcTaskPreparations.ExternalFacts bound(ExternalOperationPort.ExecutionContext context,MinutesExternalPreparation.Request request){var facts=issuer.requireExternal(context);require(facts.spec().equals(request.spec)&&facts.taskId().equals(request.taskId)&&facts.executionNo()==1&&facts.requestHash().equals(request.external.executionRequestHash())&&facts.requestManifest().equals(request.external.requestManifest()),PROVENANCE_UNAVAILABLE);return facts;}
 public void writeMarked(PreparedDomain held,ExternalOperationPort.ExecutionContext context,ExternalOperationPort.PreparedRequest value){var request=installed().request(value);issuer.requireExternal(held,context);bound(context,request);var p=(Existing)issuer.value(held);MinutesExternalPreparation.sameSources(request.input.snapshot().graph(),p.graph);require(request.input.actor().equals(p.actor),PROVENANCE_UNAVAILABLE);}
 public ama.contract.ExternalContracts.ExternalObservation verifyRemoteFact(TaskSpec actual,ExternalOperationPort.ExecutionContext context,ExternalOperationPort.PreparedObservation value){var observation=installed().observation(value);var facts=bound(context,observation.request);require(actual.equals(facts.spec())&&facts.operationId().equals(observation.token.operationId())&&facts.executionId().equals(observation.token.executionId()),PROVENANCE_UNAVAILABLE);return observation.fact;}
 public TaskResult writeCurrent(PreparedDomain held,ExternalOperationPort.ExecutionContext context,ExternalOperationPort.PreparedObservation value){var observation=installed().observation(value);issuer.requireExternal(held,context);bound(context,observation.request);var p=(Existing)issuer.value(held);MinutesExternalPreparation.sameSources(observation.request.input.snapshot().graph(),p.graph);if(observation.fact.outcome()==ama.contract.ExternalContracts.ExternalOutcome.FAILED_ZERO_EFFECT)return new TaskResult(Outcome.FAILED,null,observation.fact.errorCode());if(observation.localError!=null)return new TaskResult(Outcome.FAILED,null,observation.localError);authority.claimMinutesWrite(p.scope,p.gate,p.actor,p.graph);return new TaskResult(Outcome.SUCCEEDED,writer.write(held,context,observation,p.graph),null);}
 public void validateStoredResult(PreparedDomain held,ExternalOperationPort.ExecutionContext context,ExternalOperationPort.PreparedObservation value,TaskResult result){var observation=installed().observation(value);issuer.requireExternal(held,context);bound(context,observation.request);if(result.outcome()==Outcome.SUCCEEDED)writer.validate(held,context,observation,result.output());else require(result.output()==null&&Objects.equals(result.errorCode(),observation.localError==null?observation.fact.errorCode():observation.localError),PROVENANCE_UNAVAILABLE);}

 public Optional<PublicationPreparation> prelockedPublication(PreparedDomain held){var value=issuer.value(held);return value instanceof Existing p?Optional.ofNullable(p.publication):Optional.empty();}
 public Optional<Retention> prepareRetention(PreparedDomain held,ExternalOperationPort.ExecutionContext context,ExternalOperationPort.PreparedObservation value){var observation=installed().observation(value);issuer.requireExternal(held,context);bound(context,observation.request);var p=(Existing)issuer.value(held);if(observation.plan==null||!observation.request.input.actor().equals(p.actor))return Optional.empty();MinutesExternalPreparation.sameSources(observation.request.input.snapshot().graph(),p.graph);return retention.prepare(held,context,p.lockedRoot,p.actor);}
 public ama.contract.TaskContracts.TypedRef retainStale(Retention capability,ExternalOperationPort.PreparedObservation value){var invocation=retention.requireInvocation(capability);var observation=installed().observation(value);bound(invocation.context(),observation.request);var p=(Existing)issuer.value(invocation.domain());authority.claimMinutesWrite(p.scope,p.gate,p.actor,p.graph);return writer.writeRetained(retention,capability,observation,p.graph);}
 public void validateRetained(Retention capability,ExternalOperationPort.PreparedObservation value,ama.contract.TaskContracts.TypedRef candidate){retention.require(capability);writer.validateRetained(retention,capability,installed().observation(value),candidate);}
 public boolean verifyReplay(PreparedDomain held,ExternalOperationPort.ExecutionContext context,ExternalOperationPort.PreparedObservation value,StoredResult stored){var observation=installed().observation(value);issuer.requireExternal(held,context);bound(context,observation.request);var p=(Existing)issuer.value(held);MinutesExternalPreparation.sameSources(observation.request.input.snapshot().graph(),p.graph);if(stored.state().equals("SUCCEEDED")&&observation.plan!=null&&stored.errorCode()==null){writer.validate(held,context,observation,stored.output());return true;}if(stored.state().equals("STALE")&&stored.output()==null&&"BUSINESS_FENCED".equals(stored.errorCode())&&observation.plan!=null){writer.validateStaleReplay(held,context,observation);return true;}return stored.state().equals("FAILED")&&stored.output()==null&&Objects.equals(stored.errorCode(),observation.localError==null?observation.fact.errorCode():observation.localError);}
 static void shape(TaskSpec spec){require("MINUTES_GENERATE_V1".equals(spec.type())&&"MINUTES_GENERATE".equals(spec.pool())&&"MEETING".equals(spec.subject().kind())&&"GENERATION_INPUT".equals(spec.input().kind())&&spec.priority()==0&&spec.maxAttempts()==3,PROVENANCE_UNAVAILABLE);}
}
